const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error(
    'job_id must be a valid UUID'
  );
}

return [
  {
    json: {
      job_id: jobId,
    },
  },
];

if (!$json.job_exists) {
  throw new Error(
    `Job ${$json.requested_job_id} was not found`
  );
}

if (!$json.eligible) {
  throw new Error(
    `Job ${$json.job_id} is not eligible for script planning: ` +
    `status=${$json.status}, current_stage=${$json.current_stage}`
  );
}

return [
  {
    json: {
      job_id: $json.job_id,
      topic: $json.topic,
      language_code: $json.language_code,
      target_duration_seconds:
        $json.target_duration_seconds,
      status: $json.status,
      current_stage: $json.current_stage,
    },
  },
];

const languageNames = {
  en: 'English',
  pl: 'Polish',
  ru: 'Russian',
  uk: 'Ukrainian',
};

const requiredScenesByDuration = {
  15: 4,
  30: 8,
  45: 12,
  60: 15,
};

const sceneWordPatterns = {
  en: [10, 9],
  pl: [7],
  ru: [7],
  uk: [7, 6],
};

const languageName = languageNames[$json.language_code];

if (!languageName) {
  throw new Error(
    `Unsupported language_code: ${$json.language_code}`
  );
}

const targetDurationSeconds = Number(
  $json.target_duration_seconds
);
const requiredSceneCount =
  requiredScenesByDuration[targetDurationSeconds];

if (!requiredSceneCount) {
  throw new Error(
    `Unsupported target_duration_seconds: ${$json.target_duration_seconds}`
  );
}

const sceneWordPattern =
  sceneWordPatterns[$json.language_code];

if (
  !Array.isArray(sceneWordPattern) ||
  sceneWordPattern.length === 0 ||
  sceneWordPattern.some(
    (value) => !Number.isInteger(value) || value <= 0
  )
) {
  throw new Error(
    `Missing segmented TTS word pattern for language=${$json.language_code}`
  );
}

const sceneWordCounts = Array.from(
  { length: requiredSceneCount },
  (_, index) =>
    sceneWordPattern[index % sceneWordPattern.length]
);

const totalNarrationWords = sceneWordCounts.reduce(
  (sum, value) => sum + value,
  0
);
const totalNarrationWordTolerance = Math.max(
  2,
  Math.ceil(totalNarrationWords * 0.15)
);
const minimumTotalNarrationWords =
  totalNarrationWords - totalNarrationWordTolerance;
const maximumTotalNarrationWords =
  totalNarrationWords + totalNarrationWordTolerance;
const sceneWordRanges = sceneWordCounts.map((value) => ({
  min: Math.max(5, value - 2),
  max: value + 2,
}));
const sceneWordRangeRules = sceneWordRanges
  .map((range, index) => `${index + 1}:${range.min}-${range.max}`)
  .join(', ');

const outputContract = {
  scenes: [
    {
      scene_number: 1,
      narration_words: ['One', 'spoken', 'word'],
      visual_subject_type: 'factual',
      visual_description:
        `Concrete visual description in ${languageName}`,
      visual_query:
        'English search query preserving relevant proper nouns',
    },
  ],
};

const systemPrompt = [
  'You are a short-form video script and scene planner.',
  'Return exactly one valid JSON object.',
  'Do not use Markdown or code fences.',
  'The JSON must contain only the scenes property.',
  `The scenes array must contain exactly ${requiredSceneCount} scenes.`,
  'Every scene must contain exactly these properties: scene_number, narration_words, visual_subject_type, visual_description, visual_query.',
  'Scene numbers must start at 1 and be sequential without gaps.',

  `narration_words and visual_description must be written in ${languageName}.`,
  `The words in narration_words must form natural, grammatically correct ${languageName} narration when joined with single spaces.`,
  'Use correct grammar, spelling, inflection, and punctuation.',
  'Every scene narration must be one complete standalone sentence that can be read independently.',
  'Each scene must contain exactly one sentence, not two sentences and not a sentence followed by a fragment.',
  'Do not place sentence-final punctuation on any narration_words item except the final item of that scene.',
  'Avoid abbreviations that require a period inside the sentence; spell them out instead.',
  'Never split one grammatical sentence across two or more scenes.',
  'Do not make a later scene grammatically complete an earlier scene.',
  'Start every scene sentence with a capital letter after any opening quote or bracket.',
  'End the final narration_words item of every scene with sentence-final punctuation: period, exclamation mark, question mark, or ellipsis.',

  `Allowed narration_words item-count ranges by scene_number: ${sceneWordRangeRules}.`,
  `Across all scenes, use between ${minimumTotalNarrationWords} and ${maximumTotalNarrationWords} spoken words, aiming near the calibrated target of ${totalNarrationWords}.`,
  'Do not force equal scene lengths. Use fewer words for a simple complete sentence and more words when the idea needs them, while staying inside each scene range and the aggregate range.',
  'Each narration_words item must contain exactly one spoken word token.',
  'Do not put two or more whitespace-separated words into one item.',
  'Attach punctuation to the adjacent word, for example "city," or "works."; do not use standalone punctuation items.',
  'A hyphenated form or apostrophe inside one lexical word may stay in one item.',
  'Do not add filler merely to satisfy the count. Rewrite the sentence naturally while preserving the exact item count.',
  'If the exact word count would otherwise force a fragment, simplify or rewrite that scene as a shorter complete sentence; never continue it in the next scene.',

  'All factual claims must be accurate.',
  'Do not invent or guess mechanisms, technical details, causes, names, dates, places, measurements, statistics, or terminology.',
  'Use only factual details that you can state with high confidence.',
  'If a technical or factual detail is uncertain, omit it and use a simpler accurate statement instead.',
  'Never make a specific claim merely because it sounds plausible.',

  'For explanatory, scientific, historical, engineering, or technical topics, preserve causal accuracy.',
  'Do not replace the real cause or mechanism with a simpler but false explanation.',
  'When explaining why something works or why a mechanism is required, state the actual relevant cause rather than an unrelated correlation or superficial difference.',
  'When describing a process, keep every cause-and-effect step internally consistent with the previous and following scenes.',
  'Do not introduce pumps, motors, pressure systems, mechanical devices, measurements, named components, or other implementation details unless you are confident they are actually part of the described mechanism.',
  'Prefer a conservative high-confidence explanation over a more detailed explanation that may contain an incorrect technical claim.',

  'Each visual_description must directly depict the same main subject, action, mechanism, or event described by that scene narration.',
  'Prefer the primary visual moment described by the narration, not a secondary supporting detail.',
  'Do not describe a visual that introduces a different action or concept from the narration.',
  'Use the correct official spelling of real names and places when applicable.',

  'visual_subject_type must be exactly "factual" or "generic".',
  'Use "factual" whenever accurate explanatory sourcing matters: named or identifiable real-world subjects, scientific or engineering mechanisms, anatomy, technical components, diagrams, schematics, maps, interfaces/screens, cross-sections, molecules, forces, vectors, process illustrations, historical documents/events, machines, structures, products, places, people, organizations, or any scene where a merely decorative stock photo would fail to show the requested information.',
  'Use "generic" only when an ordinary stock photo or broad illustrative lifestyle/action/setting image is genuinely sufficient and no exact mechanism, diagram, interface, anatomy, map, component, or identifiable subject must be shown.',
  'If visual_query or visual_description explicitly asks for a diagram, schematic, cross-section, map, screen/interface, anatomy, molecule, force/load/tension/vector, technical component, or explanatory mechanism, classify the scene as factual.',

  'visual_query must be written in English, preserve relevant official names and proper nouns, contain no more than 100 characters, and be unique across scenes ignoring letter case.',
  'visual_query must search for the same primary visual subject or action described by visual_description.',
  'Do not add unrelated organizations, locations, people, brands, or technical terms to visual_query merely to make the search look more specific.',

  'Every narration_words item, visual_description, and visual_query must be non-empty.',
  'The complete narration must fit the requested target video duration at the normal configured TTS speaking pace.',
  'Do not include duration_seconds or choose a concrete visual asset/provider.',
  'Do not include titles, explanations, comments, or additional properties.',
].join('\n');

const userPrompt = [
  `Topic: ${$json.topic}`,
  `Language: ${languageName} (${$json.language_code})`,
  `Target video duration: ${targetDurationSeconds} seconds`,
  `Required scene count: ${requiredSceneCount}`,
  `Allowed narration_words item-count ranges by scene_number: ${sceneWordRangeRules}`,
  `Required aggregate spoken-word range: ${minimumTotalNarrationWords}-${maximumTotalNarrationWords}; calibrated target: ${totalNarrationWords}`,
  '',
  `Create a coherent short-form video script divided into exactly ${requiredSceneCount} scenes.`,
  'Each scene must introduce a meaningful visual change and remain coherent with the scenes around it.',
  'Build the explanation in a logical order so each scene follows naturally from the previous scene.',
  'For factual or technical topics, prioritize accuracy over extra detail.',
  'Before finalizing the plan, internally check that each factual statement and cause-and-effect relationship is consistent with the rest of the script.',
  'Classify each scene as factual or generic according to the system instructions.',
  '',
  'The JSON example below shows the shape of one scene only; the example narration_words length is illustrative only.',
  `Your actual scenes array must contain exactly ${requiredSceneCount} scenes, and each narration_words array must stay inside its scene-specific range: ${sceneWordRangeRules}.`,
  `The complete script must stay inside the aggregate ${minimumTotalNarrationWords}-${maximumTotalNarrationWords} spoken-word range.`,
  'The factual value in the example is only an example; choose factual or generic independently for every scene.',
  'Required JSON structure:',
  JSON.stringify(outputContract),
].join('\n');

return [
  {
    json: {
      ...$json,
      planning_request: {
        language_name: languageName,
        required_scene_count: requiredSceneCount,
        narration_word_budget_source:
          'segmented_production_calibration_v4_variable_ranges_gemini_3_6',
        scene_word_counts: sceneWordCounts,
        scene_word_ranges: sceneWordRanges,
        total_narration_words: totalNarrationWords,
        minimum_total_narration_words: minimumTotalNarrationWords,
        maximum_total_narration_words: maximumTotalNarrationWords,
        system_prompt: systemPrompt,
        user_prompt: userPrompt,
        output_contract: outputContract,
      },
    },
  },
];

