parameters.jsCode:
const response = $input.first().json;
const job = $('Build Planning Request').first().json;

function validatePlan() {
if (
  !job ||
  typeof job.job_id !== 'string' ||
  job.job_id.trim() === ''
) {
  throw new Error('Original job data is unavailable');
}

const requiredScenesByDuration = {
  15: 4,
  30: 8,
  45: 12,
  60: 15,
};

const targetDurationSeconds = Number(
  job.target_duration_seconds
);
const requiredSceneCount =
  requiredScenesByDuration[targetDurationSeconds];
const sceneWordCounts =
  job.planning_request?.scene_word_counts;
const sceneWordRanges =
  job.planning_request?.scene_word_ranges;
const expectedTotalNarrationWords = Number(
  job.planning_request?.total_narration_words
);
const minimumTotalNarrationWords = Number(
  job.planning_request?.minimum_total_narration_words
);
const maximumTotalNarrationWords = Number(
  job.planning_request?.maximum_total_narration_words
);

if (!requiredSceneCount) {
  throw new Error(
    `Unsupported target_duration_seconds: ${job.target_duration_seconds}`
  );
}

if (
  job.planning_request?.required_scene_count !==
  requiredSceneCount
) {
  throw new Error(
    `Planning request scene count mismatch: expected ${requiredSceneCount}, received ${job.planning_request?.required_scene_count}`
  );
}

if (
  !Array.isArray(sceneWordCounts) ||
  sceneWordCounts.length !== requiredSceneCount ||
  sceneWordCounts.some(
    (value) => !Number.isInteger(value) || value <= 0
  ) ||
  !Array.isArray(sceneWordRanges) ||
  sceneWordRanges.length !== requiredSceneCount ||
  sceneWordRanges.some(
    (range) =>
      !Number.isInteger(range?.min) ||
      !Number.isInteger(range?.max) ||
      range.min <= 0 ||
      range.max < range.min
  ) ||
  expectedTotalNarrationWords !==
    sceneWordCounts.reduce((sum, value) => sum + value, 0) ||
  !Number.isInteger(minimumTotalNarrationWords) ||
  !Number.isInteger(maximumTotalNarrationWords) ||
  minimumTotalNarrationWords <= 0 ||
  maximumTotalNarrationWords < minimumTotalNarrationWords ||
  expectedTotalNarrationWords < minimumTotalNarrationWords ||
  expectedTotalNarrationWords > maximumTotalNarrationWords
) {
  throw new Error('Planning request word budget is invalid');
}

if (
  !Array.isArray(response.candidates) ||
  response.candidates.length !== 1
) {
  throw new Error(
    'Gemini response must contain exactly one candidate'
  );
}

const candidate = response.candidates[0];

if (candidate.finishReason !== 'STOP') {
  throw new Error(
    `Gemini generation did not finish normally: ${
      candidate.finishReason ?? 'missing finishReason'
    }`
  );
}

const parts = candidate.content?.parts;

if (!Array.isArray(parts)) {
  throw new Error(
    'Gemini response does not contain content.parts'
  );
}

const textParts = parts.filter(
  (part) =>
    typeof part?.text === 'string' &&
    part.text.trim() !== ''
);

if (textParts.length !== 1) {
  throw new Error(
    `Expected exactly one non-empty text part, received ${textParts.length}`
  );
}

let plan;

try {
  plan = JSON.parse(textParts[0].text);
} catch (error) {
  throw new Error(
    `Gemini returned invalid JSON: ${error.message}`
  );
}

if (
  plan === null ||
  typeof plan !== 'object' ||
  Array.isArray(plan)
) {
  throw new Error(
    'Planning result must be a JSON object'
  );
}

const rootKeys = Object.keys(plan);

if (
  rootKeys.length !== 1 ||
  !Object.prototype.hasOwnProperty.call(
    plan,
    'scenes'
  )
) {
  throw new Error(
    'Planning result must contain only the scenes property'
  );
}

if (!Array.isArray(plan.scenes)) {
  throw new Error(
    'Planning result scenes must be an array'
  );
}

if (plan.scenes.length !== requiredSceneCount) {
  throw new Error(
    `Planning result must contain exactly ${requiredSceneCount} scenes for ${targetDurationSeconds} seconds; received ${plan.scenes.length}`
  );
}

const requiredSceneFields = [
  'scene_number',
  'narration_words',
  'visual_subject_type',
  'visual_description',
  'visual_query',
];

const allowedSubjectTypes = new Set([
  'factual',
  'generic',
]);
const seenVisualQueries = new Set();
let actualNarrationWordCount = 0;
let totalExtraWordsFromPackedItems = 0;
const actualSceneWordCounts = [];

const scenes = plan.scenes.map((scene, index) => {
  const expectedSceneNumber = index + 1;

  if (
    scene === null ||
    typeof scene !== 'object' ||
    Array.isArray(scene)
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} must be an object`
    );
  }

  const sceneKeys = Object.keys(scene);
  const missingFields = requiredSceneFields.filter(
    (field) =>
      !Object.prototype.hasOwnProperty.call(
        scene,
        field
      )
  );
  const unexpectedFields = sceneKeys.filter(
    (field) =>
      !requiredSceneFields.includes(field)
  );

  if (missingFields.length > 0) {
    throw new Error(
      `Scene ${expectedSceneNumber} is missing fields: ${missingFields.join(', ')}`
    );
  }

  if (unexpectedFields.length > 0) {
    throw new Error(
      `Scene ${expectedSceneNumber} contains unexpected fields: ${unexpectedFields.join(', ')}`
    );
  }

  if (
    !Number.isInteger(scene.scene_number) ||
    scene.scene_number !== expectedSceneNumber
  ) {
    throw new Error(
      `Scene number must be sequential: expected ${expectedSceneNumber}, received ${scene.scene_number}`
    );
  }

  if (!Array.isArray(scene.narration_words)) {
    throw new Error(
      `Scene ${expectedSceneNumber} narration_words must be an array`
    );
  }

  const expectedSceneWordCount =
    sceneWordCounts[index];
  const sceneWordRange = sceneWordRanges[index];

  if (
    scene.narration_words.length < sceneWordRange.min ||
    scene.narration_words.length > sceneWordRange.max
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} narration_words must contain ${sceneWordRange.min}-${sceneWordRange.max} items; received ${scene.narration_words.length}`
    );
  }

  const narrationWords = [];

  for (let wordIndex = 0; wordIndex < scene.narration_words.length; wordIndex++) {
    const packedToken =
      typeof scene.narration_words[wordIndex] === 'string'
        ? scene.narration_words[wordIndex].trim()
        : '';

    if (!packedToken) {
      throw new Error(
        `Scene ${expectedSceneNumber} narration word ${wordIndex + 1} is empty or invalid`
      );
    }

    const unpackedWords = packedToken.split(/\s+/u);

    if (unpackedWords.length > 2) {
      throw new Error(
        `Scene ${expectedSceneNumber} narration item ${wordIndex + 1} contains too many packed words: ${packedToken}`
      );
    }

    for (const token of unpackedWords) {
      if (!/[\p{L}\p{N}]/u.test(token)) {
        throw new Error(
          `Scene ${expectedSceneNumber} narration item ${wordIndex + 1} contains punctuation-only content: ${token}`
        );
      }

      narrationWords.push(token);
    }
  }

  const actualSceneWordCount = narrationWords.length;
  if (
    actualSceneWordCount < sceneWordRange.min ||
    actualSceneWordCount > sceneWordRange.max
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} contains ${actualSceneWordCount} spoken words; allowed range=${sceneWordRange.min}-${sceneWordRange.max}`
    );
  }

  actualNarrationWordCount += actualSceneWordCount;
  actualSceneWordCounts.push(actualSceneWordCount);
  totalExtraWordsFromPackedItems +=
    actualSceneWordCount - scene.narration_words.length;

  for (let tokenIndex = 0; tokenIndex < narrationWords.length - 1; tokenIndex++) {
    if (/[.!?…](?:["'»”’])?$/u.test(narrationWords[tokenIndex])) {
      throw new Error(
        `Scene ${expectedSceneNumber} narration must contain exactly one complete sentence; sentence-final punctuation appeared before the final word: ${narrationWords[tokenIndex]}`
      );
    }
  }

  const narration = narrationWords.join(' ');

  const firstLetterMatch = narration.match(/\p{L}/u);
  if (firstLetterMatch) {
    const firstLetter = firstLetterMatch[0];
    const upper = firstLetter.toLocaleUpperCase(job.language_code);
    const lower = firstLetter.toLocaleLowerCase(job.language_code);
    if (firstLetter === lower && upper !== lower) {
      throw new Error(
        `Scene ${expectedSceneNumber} narration must start as a standalone sentence with a capital letter: ${narration}`
      );
    }
  }

  if (!/[.!?…](?:["'»”’])?$/u.test(narration)) {
    throw new Error(
      `Scene ${expectedSceneNumber} narration must end with sentence-final punctuation and must not continue into the next scene: ${narration}`
    );
  }

  const visualDescription =
    typeof scene.visual_description === 'string'
      ? scene.visual_description.trim()
      : '';
  const visualQuery =
    typeof scene.visual_query === 'string'
      ? scene.visual_query.trim()
      : '';

  if (!narration) {
    throw new Error(
      `Scene ${expectedSceneNumber} has empty narration after joining words`
    );
  }

  if (!visualDescription) {
    throw new Error(
      `Scene ${expectedSceneNumber} has an empty or invalid visual_description`
    );
  }

  if (!visualQuery) {
    throw new Error(
      `Scene ${expectedSceneNumber} has an empty or invalid visual_query`
    );
  }

  if (
    typeof scene.visual_subject_type !== 'string' ||
    !allowedSubjectTypes.has(scene.visual_subject_type)
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} has invalid visual_subject_type: ${scene.visual_subject_type}`
    );
  }

  const factualIntentText = `${visualDescription} ${visualQuery}`.toLowerCase();
  const factualIntentPattern = /\b(diagram|schematic|cross[- ]?section|anatomy|map|screen|interface|molecule|vector|force|forces|load|tension|pressure|mechanism|technical|component|internal|circuit|flowchart|structure|anchorage|foundation)\b/u;
  const normalizedSubjectType =
    scene.visual_subject_type === 'factual' || factualIntentPattern.test(factualIntentText)
      ? 'factual'
      : 'generic';

  if (visualQuery.length > 100) {
    throw new Error(
      `Scene ${expectedSceneNumber} visual_query exceeds 100 characters: ${visualQuery.length}`
    );
  }

  const normalizedVisualQuery = visualQuery.toLowerCase();
  if (seenVisualQueries.has(normalizedVisualQuery)) {
    throw new Error(
      `Scene ${expectedSceneNumber} duplicates visual_query case-insensitively: ${visualQuery}`
    );
  }
  seenVisualQueries.add(normalizedVisualQuery);

  return {
    scene_number: expectedSceneNumber,
    narration,
    visual_subject_type: normalizedSubjectType,
    visual_description: visualDescription,
    visual_query: visualQuery,
  };
});

const plannedNarrationWordUnits = sceneWordCounts.reduce(
  (sum, value) => sum + value,
  0
);

if (plannedNarrationWordUnits !== expectedTotalNarrationWords) {
  throw new Error(
    `Planning narration unit target mismatch: expected ${expectedTotalNarrationWords}, received ${plannedNarrationWordUnits}`
  );
}

if (
  actualNarrationWordCount < minimumTotalNarrationWords ||
  actualNarrationWordCount > maximumTotalNarrationWords
) {
  throw new Error(
    `Planning narration contains ${actualNarrationWordCount} spoken words; required aggregate range=${minimumTotalNarrationWords}-${maximumTotalNarrationWords}, calibrated target=${expectedTotalNarrationWords}`
  );
}

const totalNarrationCharacters = scenes.reduce(
  (sum, scene) => sum + scene.narration.length,
  0
);

return [
  {
    json: {
      job_id: job.job_id,
      topic: job.topic,
      language_code: job.language_code,
      target_duration_seconds: targetDurationSeconds,
      status: job.status,
      current_stage: job.current_stage,
      scenes,
      narration_word_count: actualNarrationWordCount,
      narration_word_unit_budget: plannedNarrationWordUnits,
      narration_word_count_minimum: minimumTotalNarrationWords,
      narration_word_count_maximum: maximumTotalNarrationWords,
      narration_packed_extra_words: totalExtraWordsFromPackedItems,
      narration_word_counts_by_scene: actualSceneWordCounts,
      narration_word_targets_by_scene: sceneWordCounts,
      narration_word_ranges_by_scene: sceneWordRanges,
      narration_character_count: totalNarrationCharacters,
      narration_word_budget_source:
        job.planning_request.narration_word_budget_source,
      ai_metadata: {
        provider: 'google_gemini',
        model: response.modelVersion ?? null,
        response_id: response.responseId ?? null,
        prompt_tokens:
          response.usageMetadata?.promptTokenCount ?? null,
        output_tokens:
          response.usageMetadata?.candidatesTokenCount ?? null,
        total_tokens:
          response.usageMetadata?.totalTokenCount ?? null,
      },
    },
  },
];
}

try {
  const result = validatePlan();
  return result.map((item) => ({
    ...item,
    json: {
      ...item.json,
      planning_failed: false,
      planning_error: null,
    },
  }));
} catch (error) {
  const message = String(error?.message || error || 'Unknown structured-plan validation failure').trim().slice(0, 4000);
  return [{
    json: {
      job_id: typeof job?.job_id === 'string' ? job.job_id : null,
      planning_failed: true,
      planning_error: message,
    },
  }];
}

const errorItem = $input.first()?.json ?? {};
const job = $('Require Eligible Job').first().json;

if (typeof job.job_id !== 'string' || job.job_id.trim() === '') {
  throw new Error('Validated job_id is unavailable while recording script failure');
}

const candidates = [
  errorItem.planning_error,
  errorItem.error?.message,
  errorItem.error?.description,
  errorItem.error,
  errorItem.errorMessage,
  errorItem.errorDescription,
  errorItem.message,
];

let message = candidates.find((value) => typeof value === 'string' && value.trim() !== '');

if (!message) {
  try { message = JSON.stringify(errorItem); } catch { message = ''; }
}

message = String(message || 'Unknown script planning stage failure').trim().slice(0, 4000);

return [{ json: { job_id: job.job_id, last_error: message } }];
